using System;
using System.IO;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
using UnityEditor;
namespace CampaignDemo.Editor
{
    public static class CombatEffectsVerification
    {
        static readonly List<string> results=new List<string>();
        static void Check(bool value,string name){if(!value)throw new Exception(name);results.Add("PASS "+name);}
        static BattleUnit Unit(Transform root,string id,string owner,Vector3 p)
        {var g=new GameObject(id);g.transform.SetParent(root);g.transform.position=p;var u=g.AddComponent<BattleUnit>();u.unitId=id;u.ownerId=owner;var d=ScriptableObject.CreateInstance<ArmyCombatDefinition>();d.echelon=ArmyEchelon.Squad;d.fullStrengthAttack=2;d.defense=0;d.attackRadius=1;d.visionRadius=2;u.combatDefinition=d;return u;}
        public static void Run(){try{CombatEffectsInstaller.Configure();Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText("combat-effects-verification.txt",e+"\n"+string.Join("\n",results));Debug.LogException(e);EditorApplication.Exit(1);}}
        public static void Validate()
        {
            results.Clear();var sceneWorld=UnityEngine.Object.FindObjectOfType<BattleWorld>();var root=new GameObject("Attack effects test");var w=root.AddComponent<BattleWorld>();w.enabled=false;w.setup=sceneWorld.setup;w.points=new RecoveryPoint[0];w.players=new[]{"A","B"};w.currentPlayer="A";
            var a=Unit(root.transform,"effect-A","A",new Vector3(100,100));var b=Unit(root.transform,"effect-B","B",new Vector3(100.5f,100));w.units=new[]{a,b};w.Initialize();var events=new List<CombatEffectEvent>();Action<CombatEffectEvent> recorder=e=>events.Add(e);w.CombatEffectOccurred+=recorder;
            float before=b.Personnel;w.Tick(.1f);Check(events.Count==2&&events.TrueForAll(e=>e.Stage==CombatEffectStage.DirectAttack),"ordinary positive attacks notify for both combatants");Check(b.Personnel<before,"damage still applies with notifications");Check(events[0].SourcePosition==a.transform.position&&events[0].TargetPosition==b.transform.position,"notification snapshots source and target coordinates");
            a.Initialize();b.Initialize();a.combatDefinition.fullStrengthAttack=0;b.combatDefinition.fullStrengthAttack=0;events.Clear();w.Tick(.1f);Check(events.Count==0,"zero damage creates no attack effects");
            a.combatDefinition.fullStrengthAttack=2;b.combatDefinition.fullStrengthAttack=2;a.Initialize();b.Initialize();w.CombatEffectOccurred-=recorder;w.Tick(.1f);float baseline=b.Personnel;
            a.Initialize();b.Initialize();Action<CombatEffectEvent> faulty=e=>throw new Exception("Expected effect failure");w.CombatEffectOccurred+=faulty;w.CombatEffectOccurred+=recorder;events.Clear();bool logging=Debug.unityLogger.logEnabled;try{Debug.unityLogger.logEnabled=false;w.Tick(.1f);}finally{Debug.unityLogger.logEnabled=logging;}Check(b.Personnel==baseline&&events.Count==2,"broken effect subscriber cannot stop damage or other subscribers");w.CombatEffectOccurred-=faulty;
            var presenter=root.AddComponent<CombatEffectPresenter>();presenter.world=w;var renderer=root.AddComponent<PrefabCombatEffectPlayer>();renderer.presenter=presenter;presenter.effectPlayer=renderer;var profile=ScriptableObject.CreateInstance<CombatEffectProfile>();profile.directAttackInterval=.5f;presenter.defaultProfile=profile;presenter.BindWorld(w);
            a.Initialize();b.Initialize();w.Intel.Reset(b);w.currentPlayer="A";a.transform.position=new Vector3(100,100);b.transform.position=new Vector3(110,100);
            var hidden=CombatEffectEvent.Direct(b,a.unitId,a.ownerId,a.transform.position);
            Check(presenter.TryCreateCue(hidden,out var cue)&&!cue.HasSource&&cue.HasTarget,"visible hit does not disclose unseen shooter");Check(cue.SourcePosition==Vector3.zero&&!cue.HasSourceRole,"hidden shooter position and role removed before player interface");
            b.transform.position=new Vector3(100.5f,100);b.HideInForest();Check(presenter.TryCreateCue(CombatEffectEvent.Direct(b,a.unitId,a.ownerId,a.transform.position),out cue)&&!cue.HasSource,"concealed source does not disclose muzzle or trajectory");b.RevealForest();w.Intel.Reset(b);
            Check(presenter.TryCreateCue(CombatEffectEvent.Direct(b,a.unitId,a.ownerId,a.transform.position),out cue)&&cue.HasSource&&!cue.HasSourceRole,"unidentified visible source uses generic effect profile");w.Intel.Identify("A",b);Check(presenter.TryCreateCue(CombatEffectEvent.Direct(b,a.unitId,a.ownerId,a.transform.position),out cue)&&cue.HasSourceRole,"identified source may use role specific effects");
            a.transform.position=new Vector3(100,100);b.transform.position=new Vector3(110,100);var unseen=new CombatEffectEvent(CombatEffectStage.DirectAttack,"unknown-B","B",UnitRole.Tank,true,new Vector3(120,120),"unknown-C","B",new Vector3(121,120));Check(!presenter.TryCreateCue(unseen,out cue),"fully unseen combat filtered");
            var impact=new CombatEffectEvent(CombatEffectStage.ArtilleryImpact,"effect-B","B",UnitRole.Artillery,true,b.transform.position,null,null,a.transform.position,.5f);Check(presenter.TryCreateCue(impact,out cue)&&cue.HasTarget&&!cue.HasSource,"shell impact never discloses remote artillery origin");var offscreen=new CombatEffectEvent(CombatEffectStage.SupportImpact,null,"B",UnitRole.Artillery,false,Vector3.zero,null,null,new Vector3(200,200),1);Check(!presenter.TryCreateCue(offscreen,out cue),"unseen shell impact filtered");
            var launch=new CombatEffectEvent(CombatEffectStage.ArtilleryLaunch,a.unitId,"A",UnitRole.Artillery,true,a.transform.position,null,null,new Vector3(105,100),1);Check(presenter.TryCreateCue(launch,out cue)&&cue.HasSource&&cue.HasTarget,"own artillery launch retains own commanded destination");var enemyLaunch=new CombatEffectEvent(CombatEffectStage.ArtilleryLaunch,b.unitId,"B",UnitRole.Artillery,true,b.transform.position,null,null,a.transform.position,1);Check(!presenter.TryCreateCue(enemyLaunch,out cue),"unseen enemy artillery launch filtered");
            var direct=CombatEffectEvent.Direct(a,null,"B",a.transform.position+Vector3.right);presenter.Reset();presenter.Present(direct,1);var timings=(Dictionary<string,double>)typeof(CombatEffectPresenter).GetField("nextDirect",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(presenter);Check(timings[a.unitId]==1.5,"direct visual interval comes from profile");presenter.Present(direct,1.1);Check(timings[a.unitId]==1.5,"repeated ticks do not flood effect player");presenter.Present(direct,1.6);Check(timings[a.unitId]==2.1,"visual repeats when display interval expires");w.SetPlayer("B");Check(timings.Count==0,"player change resets visual timers and clears old view");w.currentPlayer="A";
            a.Initialize();b.Initialize();b.transform.position=new Vector3(110,100);var logistics=root.AddComponent<LogisticsWorld>();logistics.enabled=false;logistics.world=w;var cg=new GameObject("effect collector");cg.transform.SetParent(root.transform);cg.transform.position=new Vector3(100.3f,100);var collector=cg.AddComponent<ResourceCollector>();collector.collectorId="collector-effects";collector.ownerId="B";collector.Initialize();logistics.collectors.Add(collector);events.Clear();Check(logistics.AttackCollector(a,.1f)&&events.Count==1&&events[0].TargetIsCollector,"collector attacks share the effect interface");
            var combined=root.AddComponent<CombinedArmsWorld>();combined.enabled=false;combined.world=w;combined.engineering=ScriptableObject.CreateInstance<EngineeringDefinition>();var artillery=ScriptableObject.CreateInstance<ArtilleryDefinition>();artillery.delaySeconds=1;artillery.damage=1;var battery=a.gameObject.AddComponent<ArtilleryBattery>();battery.definition=artillery;a.combatDefinition.role=UnitRole.Artillery;a.Initialize();events.Clear();Check(battery.Fire(w,"A",new Vector3(100.4f,100)).accepted&&events.Count==1&&events[0].Stage==CombatEffectStage.ArtilleryLaunch,"accepted artillery fire publishes launch");Vector3 sourceAtLaunch=a.transform.position;a.transform.position+=Vector3.up;combined.Tick(.5f);Check(events.Count==1,"no impact effect before shell delay");combined.Tick(.6f);Check(events.Count==2&&events[1].Stage==CombatEffectStage.ArtilleryImpact,"shell publishes impact at damage time");Check(events[1].SourcePosition==sourceAtLaunch,"shell uses fire time snapshot after source movement");Check(events[1].Radius==artillery.blastRadius,"blast radius provided to display layer");
            combined.supportDefinition=artillery;events.Clear();Check(combined.Support("A",a.transform.position).accepted&&events.Count==1&&events[0].Stage==CombatEffectStage.SupportLaunch,"support publishes its own launch event");combined.Tick(1.1f);Check(events.Count==2&&events[1].Stage==CombatEffectStage.SupportImpact,"support publishes impact separately from battery");
            presenter.enabled=false;a.combatDefinition.role=UnitRole.Infantry;a.transform.position=new Vector3(100,100);b.transform.position=new Vector3(100.5f,100);a.Initialize();b.Initialize();before=b.Personnel;w.Tick(.1f);Check(b.Personnel<before,"disabled presentation never stops combat");
            UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(profile);UnityEngine.Object.DestroyImmediate(artillery);File.WriteAllText("combat-effects-verification.txt",results.Count+" checks passed\n"+string.Join("\n",results));Debug.Log("COMBAT_EFFECTS_VERIFY_PASS "+results.Count);
        }
    }
}

